from lib import *
S = SS('x93')
steps = [
    step("@Version 做了什么。AccV 实体的 version 字段标了 @Version,初始 version=0,余额 100。每次修改发出的 SQL 都是 update accv set balance=?,version=? where id=? and version=?——version 同时被改成新值并出现在 where 里。连续修改 3 次之后 version=3、balance=130。再模拟两个事务撞车:A 先读到 version=3,B 完整地改完(+1000)并提交,A 再改(+1)提交:A 的 update 在 where version=3 上命中 0 行,抛 ObjectOptimisticLockingFailureException(Unexpected row count: expected row count 1 but was 0)。最终 balance=1130,version=4——B 的 +1000 保住了,A 的 +1 没有写进去,A 被告知失败而不是悄悄覆盖。", t=tl(S(1)), mark=lidx(S(1), 'A 提交失败', 'SQL:update'), done=lidx(S(1), '初始 version', '3 次修改之后', '最终 balance = 1130'), b=bars([['3 次修改之后的 version', 3, '3'], ['撞车之后的 version', 4, '4'], ['A 的 update 命中的行数', 0, '0'], ['B 的更新是否保住(1=是)', 1, '是']], 4, done=[0, 1, 3], mark=[2]), kv=KV([['SQL', 'set version=新值 … where version=旧值'], ['撞车', '命中 0 行 → ObjectOptimisticLockingFailureException'], ['先提交的赢', '后提交的得到异常,不会静默覆盖'], ['version', '每次修改加 1']], ['SQL'])),
    step("8 个线程各给同一行加 25 次 1(余额从 100 开始,应得 300),三种做法。没有 @Version:最终 balance=131,比应得的少 169,没有任何报错,200 次尝试全部「成功」——这是丢失更新。有 @Version、冲突了就放弃:最终 131,乐观锁冲突 169 次、放弃 169 次,丢失的更新变成了明确的失败。有 @Version、失败就重试(最多 20 次,随机退避):最终 balance=300,一个都没丢;乐观锁冲突 72 次(都被重试掉了),放弃 0 次,总尝试 272 次,用时 174 ms,比不重试的 53 ms 慢,但结果是对的。乐观锁本身不能让并发写成功,它只负责「发现冲突」,要成功得靠重试。", t=tl(S(2)), mark=lidx(S(2), '没有 @Version', '失败就放弃'), done=lidx(S(2), '失败重试'), b=bars([['没有 @Version:最终余额(应为 300)', 131, '131'], ['@Version 失败就放弃:最终余额', 131, '131'], ['@Version 失败重试:最终余额', 300, '300'], ['重试方案的乐观锁冲突次数', 72, '72'], ['重试方案的总尝试次数', 272, '272']], 300, mark=[0, 1], done=[2], cur=[3, 4]), kv=KV([['没有 @Version', '少了 169,没有任何报错'], ['有 @Version 不重试', '169 次失败,把丢失变成显式失败'], ['有 @Version 加重试', '余额 300,冲突 72 次,尝试 272 次'], ['代价', '重试方案 174 ms,不重试 53 ms']], ['有 @Version 加重试'])),
    step("批量 JPQL 更新会绕过 @Version。A 先读到余额 100,B 在另一个事务里用 @Modifying 的批量更新给余额加 50,然后 A 加 10 并提交。B 用不带 versioned 的 update AccV set balance = balance + ?:A 提交成功,最终 balance=110(两笔都保住应是 160),version=1——B 的 +50 被覆盖了,因为批量更新没有改 version,A 的 where version=0 仍然命中。B 改用 update versioned:A 提交失败,抛 ObjectOptimisticLockingFailureException,最终 balance=150(B 的 +50 保住),version=1。所以绕过实体、直接批量更新的代码,要写 update versioned,否则会和有 @Version 的实体更新互相覆盖。", t=tl(S(3)), mark=lidx(S(3), 'update(不带 versioned)'), done=lidx(S(3), 'update versioned'), b=bars([['不带 versioned:最终余额(应为 160)', 110, '110(丢了 50)'], ['update versioned:最终余额', 150, '150(A 失败)'], ['应有的余额(两笔都保住)', 160, '160']], 160, mark=[0], done=[1], cur=[2]), kv=KV([['批量 update', '不改 version,会和实体更新互相覆盖'], ['update versioned', 'version 加 1,实体更新方会冲突失败'], ['结果', '110(丢更新)对 150(冲突后 A 失败)'], ['建议', '批量更新写 versioned,或自己 version = version + 1']], ['批量 update'])),
    step("表单场景:页面带着旧 version 回来保存。A 打开编辑页时读到 version=0,期间别人把余额改成 500(库里 version=1)。A 带着 version=0 的游离对象 repo.save:抛 ObjectOptimisticLockingFailureException(Row was already updated or deleted by another transaction for entity [demo.AccV with id '1'])。两个相关的坑:一是游离对象不带 version(version=null),Spring Data 把它当成新对象去 persist,结果是主键冲突 DataIntegrityViolationException: Duplicate entry '1' for key 'accv.PRIMARY';二是不用 save 游离对象,而是重新 find 最新的实体、再把表单里的字段拷进去——这时拿到的是最新的 version,提交成功,最终 balance=200、version=2,别人改的 500 被静默覆盖了。乐观锁要起作用,旧 version 必须一路带回到更新语句。", t=tl(S(4)), mark=lidx(S(4), '没带 version', '重新 find'), done=lidx(S(4), '带旧 version=0'), b=bars([['带旧 version 保存:结果(0=失败)', 0, '失败:ObjectOptimisticLockingFailureException'], ['丢了 version 的游离对象:结果', 0, '失败:主键冲突'], ['重新 find 再拷字段:结果(1=成功)', 1, '成功,覆盖了 500']], 1, done=[0], mark=[1, 2]), kv=KV([['带旧 version 的 save', '冲突,抛 ObjectOptimisticLockingFailureException'], ['version=null 的 save', '当作新对象,主键冲突'], ['find 再拷字段', '拿到的是最新 version,静默覆盖'], ['要点', '旧 version 必须带回到 where version=?']], ['find 再拷字段'])),
]
A = mkartx('x93', 93, 'Spring,Data,JPA,乐观锁,Version,重试,并发,真实验证,动画演示',
    '实测 JPA 的 @Version:每次更新是 where id=? and version=?,撞车时命中 0 行抛 ObjectOptimisticLockingFailureException;8 个线程各加 25 次,没有 @Version 少了 169、有 @Version 不重试放弃 169 次、重试后一个不丢(冲突 72 次);批量 JPQL 更新绕过 @Version,要写 update versioned;表单场景里丢掉旧 version 会静默覆盖。',
    '乐观锁到底是怎么发现冲突的?冲突之后该怎么办?为什么加了 @Version 还是丢更新?批量 update 会不会绕过它?这篇在 Spring Boot 4.0.8、Hibernate 7、MySQL 上用 8 个线程撞同一行实测。',
    [('169 → 0', '8 个线程各加 25 次:没有 @Version 少了 169;有 @Version 加重试少了 0'), ('110 vs 150', '批量更新不带 versioned 时最终余额 110(丢了 50);带 versioned 时 A 失败、余额 150'), ('72 次冲突 / 272 次尝试', '重试方案里乐观锁冲突的次数,与总尝试次数')],
    [('机制', '<p>update … set version=新 … where version=旧;命中 0 行就抛 ObjectOptimisticLockingFailureException。</p>'),
     ('重试', '<p>乐观锁只发现冲突,要成功得靠重试;不重试就是显式失败而不是丢更新。</p>'),
     ('绕过', '<p>批量 JPQL 不改 version,要写 update versioned。</p>'),
     ('表单', '<p>旧 version 要带回到更新语句;丢了它就会静默覆盖。</p>')],
    steps,
    [ENV_X + '(Hibernate 7、Spring Data JPA 4 随 spring-boot-starter-data-jpa;MySQL 是本机自己起的 26.7.0 实例,默认隔离级别 REPEATABLE-READ)。一行账户余额;8 个线程各 25 次「读、加 1、提交」,线程池 16 个连接;重试是手写的循环(最多 20 次,随机退避,没有用 Spring 7 新增的重试注解);每个数字是单次运行的结果,冲突次数会随运行抖动',
     '没有验证:Spring Framework 7 / Spring Retry 的 @Retryable;悲观锁(@Lock(PESSIMISTIC_WRITE))与乐观锁的对比;时间戳型 @Version;version 字段溢出;乐观锁在大批量更新里的表现;SERIALIZABLE 隔离级别;分布式场景下的乐观锁(数据库 CAS 与应用层版本号)'],
    '乐观锁')
